style.css:
@-moz-document domain("joyland.ai") {
/* Target message containers and all nested text elements */
  [class*="message"], 
  [class*="chat-bubble"], 
  [class*="msg"], 
  [class*="bubble"],
  div[class*="content"] {
    background-color: #002366 !important; /* Dark Royal Blue */
    background-image: none !important;
  }

  /* Force all text inside those bubbles to be white */
  [class*="message"] *, 
  [class*="chat-bubble"] *, 
  [class*="msg"] * {
    color: #ffffff !important;
  }
}
